package io.github.polestarcn.companion;
import android.content.Context;import android.graphics.*;import android.os.Build;import android.widget.TextView;
/** Presentation only: never changes the reported healthy/problem/unknown decision. */
final class ConditionStyle {
 static String message(Context c,boolean problem){String fallback=problem?AppPreferences.tr(c,"请检查车辆","Check vehicle"):"All Good！";String value=AppPreferences.get(c,problem?"condition_problem_text":"condition_good_text",fallback).trim();return value.isEmpty()?fallback:value.substring(0,Math.min(80,value.length()));}
 static int color(Context c){return colorValue(AppPreferences.get(c,"condition_color","#FF6B00"),PsaDesign.ORANGE);}
 static int colorValue(String value,int fallback){try{return value.matches("#[0-9a-fA-F]{6}")?Color.parseColor(value):fallback;}catch(RuntimeException e){return fallback;}}
 static boolean summary(Context c,String value){return value!=null&&(value.trim().equals(message(c,false))||value.trim().equals(message(c,true))||value.trim().equals("All Good！")||value.trim().equals("All Good!"));}
 static Typeface typeface(Context c){int weight=EffectSettings.number(c,"all_good_weight",500,300,900);if(AppPreferences.visible(c,"ui_all_bold",false))weight=Math.max(700,weight);return Build.VERSION.SDK_INT>=28?Typeface.create(PsaDesign.regular(),weight,false):Typeface.create(weight<=300?"sans-serif-light":weight>=500?"sans-serif-medium":"sans-serif",weight>=700?Typeface.BOLD:Typeface.NORMAL);}
 static void apply(TextView v){Context c=v.getContext();if(!summary(c,v.getText().toString()))return;v.setTypeface(typeface(c));v.setTextColor(color(c));v.setTextScaleX(EffectSettings.number(c,"condition_stretch",100,50,200)/100f);v.setSingleLine(false);v.setMaxLines(3);v.setLineSpacing(0,EffectSettings.number(c,"condition_line_spacing",100,50,200)/100f);int size=EffectSettings.number(c,"condition_size",0,0,100);if(size>0){v.setTextSize(size);v.setAutoSizeTextTypeUniformWithConfiguration(6,Math.max(6,size),1,android.util.TypedValue.COMPLEX_UNIT_SP);}}
 static void focus(Canvas canvas,TextView v){if(v.getLayout()==null||!summary(v.getContext(),v.getText().toString()))return;float max=0;for(int i=0;i<v.getLayout().getLineCount();i++)max=Math.max(max,v.getLayout().getLineWidth(i));float freeX=Math.max(0,v.getWidth()-v.getPaddingLeft()-v.getPaddingRight()-max),freeY=Math.max(0,v.getHeight()-v.getPaddingTop()-v.getPaddingBottom()-v.getLayout().getHeight());canvas.translate(freeX*(EffectSettings.number(v.getContext(),"condition_focus_x",50,0,100)-50)/100f,freeY*(EffectSettings.number(v.getContext(),"condition_focus_y",50,0,100)-50)/100f);}
 static void symbol(android.view.View v){if(!"health_symbol".equals(v.getTag())||v.getLayoutParams()==null)return;int size=Math.round(18*v.getResources().getDisplayMetrics().density*EffectSettings.number(v.getContext(),"condition_check_size",100,50,250)/100f);size=Math.min(size,Math.round(36*v.getResources().getDisplayMetrics().density));android.view.ViewGroup.LayoutParams p=v.getLayoutParams();if(p.width!=size||p.height!=size){p.width=size;p.height=size;v.setLayoutParams(p);}}
 private ConditionStyle(){}
}
